import os
import json
import re

def analyze_files():
    results = {}
    # Get all .py files in the current directory and subdirectories
    py_files = []
    for root, dirs, files in os.walk('.'):
        for file in files:
            if file.endswith('.py'):
                py_files.append(os.path.join(root, file))

    for filepath in py_files:
        with open(filepath, 'r', encoding='utf-8') as f:
            lines = f.readlines()
            line_count = len(lines)

            # Extract imports using regex
            import_pattern = re.compile(r'^(?:from|import)\s+([\w\.*, ]+)', re.MULTILINE)
            imports = set()
            for line in lines:
                match = import_pattern.search(line)
                if match:
                    # Clean up the matched string to get just the module names
                    parts = match.group(1).split(',')
                    for p in parts:
                        # Remove 'from' and extra spaces
                        clean_p = p.strip().replace('from ', '')
                        if clean_p:
                            imports.add(clean_p)

            results[filepath] = {
                "line_count": line_count,
                "libraries": list(imports)
            }

    with open('result.json', 'w', encoding='utf-8') as f:
        json.dump(results, f, indent=4)
    print("Analysis complete. Results saved to result.json")

if __name__ == "__main__":
    analyze_files()
