import os
import ast
import json
from pathlib import Path

def analyze_python_files(root_dir):
    results = []
    workspace_path = Path(root_dir).resolve()

    for py_file in workspace_path.rglob("*.py"):
        # Skip the script itself to avoid self-analysis if desired, 
        # but the prompt says "all Python (.py) files". 
        # However, usually we want to exclude the analyzer itself or at least handle it.
        # I'll include all and let the user see.

        try:
            with open(py_file, 'r', encoding='..' if False else 'utf-8') as f:
                content = f.read()
                lines = content.splitlines()
                line_count = len(lines)

                # Parse imports using AST
                imports = set()
                try:
                    tree = ast.parse(content)
                    for node in ast.walk(tree):
                        if isinstance(node, ast.Import):
                            for alias in node.names:
                                imports.add(alias.name.split('.')[0])
                        elif isinstance(node, ast.ImportFrom):
                            if node.module:
                                imports.add(node.module.split('.')[0])
                except SyntaxError:
                    # If file has syntax error, we can't parse AST, but we still have line count
                    pass

                results.append({
                    "file_path": str(py_file.relative_to(workspace_path)),
                    "line_count": line_count,
                    "imports": sorted(list(imports))
                })
        except Exception as e:
            print(f"Error processing {py_file}: {e}")

    return results

if __name__ == "__main__":
    workspace_root = os.getcwd()
    analysis_data = analyze_python_files(workspace_root)

    output_file = "result.json"
    with open(output_file, 'w', encoding='utf-8') as f:
        json.dump(analysis_data, f, indent=4)
    print(f"Analysis complete. Results saved to {output_file}")
